def main():
    avatars=tomllib.loads((ROOT/'content/avatars/beta.toml').read_text(encoding='utf8'))['avatar']
    names=dict(line.split(' = ',1) for line in (ROOT/'content/i18n/pl.ftl').read_text(encoding='utf8').splitlines() if ' = ' in line)
    gallery=[]
    for avatar in avatars:
        key=avatar['key'].removeprefix('avatar.');label=names[f'avatar-{key}-name'];school,skin,drawing=PORTRAITS[key];dark,light=PALETTE[school]
        svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" role="img" aria-label="{escape(label)}"><title>{escape(label)}</title><defs><radialGradient id="bg" cx="50%" cy="30%" r="90%"><stop stop-color="{dark}"/><stop offset="1" stop-color="#1c1925"/></radialGradient><linearGradient id="metal" x2="1" y2="1"><stop stop-color="#eee1bc"/><stop offset=".4" stop-color="{light}"/><stop offset="1" stop-color="#514a43"/></linearGradient></defs><rect width="200" height="200" rx="12" fill="url(#bg)"/><circle cx="102" cy="75" r="59" fill="none" stroke="{light}" opacity=".4"/><path d="M20 181L102 36 181 181" fill="none" stroke="{light}" opacity=".15"/><g style="--coat:{dark};--skin:{skin}">{drawing}</g><rect x="4" y="4" width="192" height="192" rx="9" fill="none" stroke="#d2bb8c"/><path d="M12 30V12H30M170 12H188V30M12 170V188H30M170 188H188V170" fill="none" stroke="#e8cfa0"/></svg>'''
